-- Proof: Cindra is a REAL ribbon planet generated by the MAP-GEN itself, a THREE-PART
-- TWO-HEIGHTMAP world (ci-3yl worldgen; ci-wly rebuild).
--
-- No on_chunk_generated script paints or voids anything. This drives the actual planet
-- map_gen_settings on a fresh, fixed-seed surface and proves, on the default vertical
-- orientation (ribbon long axis = Y; hot-cold gradient = X, hot on the LEFT / west,
-- perp = -x):
--   1. FINITE PERPENDICULAR: width = SUM of the zone widths (800) voids beyond the band.
--   2. TWO INTEGRATED OCEANS: the sunward hot-lava ocean AND the nightward smooth-ice
--      ocean each generate as a SOLID contiguous sea at the map edge, seed-independent,
--      FOLDED INTO the heightmap (never stamped on top).
--   3. HEIGHTMAP RINGS: lava/ice sit in pools ringed by their crust; each ocean thins
--      toward the habitable middle.
--   4. THREE REGIONS: the hot slope is hot-family tiles, the middle is the ash mix +
--      soil, the cold slope is cold-family tiles; the families never cross the middle.
--   4a. THE HOT-SIDE FOLDS BRANCH (ci-72bw): the safe hot slope carries TWO texture
--      families (cracks and folds/pumice) over the same value segment, picked per-REGION
--      by a low-frequency selector; both converge on ash-dark and neither leaks out.
--   5. WALKABILITY: only the two lava tiles are impassable; smooth-ice is now WALKABLE.
--   6. DAMAGE: positional -- the hot ocean+inner burn, the cold inner+ocean freeze.
--   7. ZERO NAUVIS LEAKAGE. 8. NATIVE RESOURCES banded. 9. NO CLIFFS. 10. LANDABLE.
--
-- The pure zone geometry is proven in unit-tests/test_terrain + test_resource_field;
-- this proves it actually generates on a live surface.

local field = require("scripts.resource-field")
local terrain = require("scripts.terrain")
local tile_damage = require("scripts.tile-damage")

describe("cindra worldgen: a three-part two-heightmap ribbon planet (§4; ci-wly)", function()
  local s
  local ready = false
  local RY = 350

  before_each(function()
    if ready then return end
    local base = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local mgs = base.map_gen_settings
    mgs.seed = 2468
    local fd = terrain.finite_dimension()
    mgs[fd.key] = fd.value
    s = game.surfaces["cindra-worldgen-test"] or game.create_surface("cindra-worldgen-test", mgs)
    -- Radius 15 chunks (~480 tiles) covers the full x in [-400,400] out to y ~= +/-RY.
    s.request_to_generate_chunks({ 0, 0 }, 15)
    s.force_generate_chunk_requests()
    ready = true
  end)

  local function tile(x, y) return s.get_tile(x, y).name end

  local HOT_FAMILY, MIDDLE_FAMILY, COLD_FAMILY = {}, {}, {}
  for _, v in ipairs({ "lava-hot", "lava", "volcanic-smooth-stone-warm", "volcanic-cracks-hot",
                       "volcanic-cracks-warm", "volcanic-cracks", "volcanic-smooth-stone", "volcanic-ash-dark",
                       -- the ci-72bw folds branch: the hot slope's ALTERNATE texture family
                       "volcanic-folds-warm", "volcanic-folds", "volcanic-folds-flat",
                       "volcanic-ash-cracks", "volcanic-pumice-stones" }) do
    HOT_FAMILY["cindra-" .. v] = true
  end
  -- The two hot-slope families (ci-72bw), read from the single source of truth.
  local FOLDS = terrain.family_tiles("folds")
  local CRACKS = terrain.family_tiles("cracks")
  for _, v in ipairs({ "volcanic-ash-dark", "volcanic-ash-light", "volcanic-ash-flats",
                       "volcanic-ash-soil", "volcanic-soil-light", "volcanic-soil-dark" }) do
    MIDDLE_FAMILY["cindra-" .. v] = true
  end
  for _, v in ipairs({ "ice-smooth", "ice-rough", "snow-patchy", "snow-lumpy", "snow-crests", "snow-flat",
                       "dust-patchy", "dust-lumpy", "dust-crests", "dust-flat", "volcanic-ash-light" }) do
    COLD_FAMILY["cindra-" .. v] = true
  end
  local LAVA = { ["cindra-lava-hot"] = true, ["cindra-lava"] = true }
  local HOT_CRUST = {
    ["cindra-volcanic-cracks-hot"] = true, ["cindra-volcanic-cracks-warm"] = true,
    ["cindra-volcanic-smooth-stone-warm"] = true,
  }
  local COLD_RING = {}
  for _, v in ipairs({ "ice-rough", "snow-patchy", "snow-lumpy", "snow-crests", "snow-flat" }) do
    COLD_RING["cindra-" .. v] = true
  end

  local function count_in(names_set, x1, x2, y1, y2)
    local n = 0
    for _, name in ipairs(terrain.tile_names()) do
      if names_set[name] then n = n + s.count_tiles_filtered({ name = name, area = { { x1, y1 }, { x2, y2 } } }) end
    end
    return n
  end

  -- 1. FINITE PERPENDICULAR --------------------------------------------------------
  it("is finite perpendicular: the map-gen voids beyond the total width (800), interior playable", function()
    assert.are.equal("out-of-map", tile(-410, 0), "sunward (west) beyond the ribbon is void")
    assert.are.equal("out-of-map", tile(410, 0), "nightward (east) beyond the ribbon is void")
    assert.are_not.equal("out-of-map", tile(0, 0), "the middle centre is playable")
    assert.are_not.equal("out-of-map", tile(-390, 0), "the hot-lava ocean edge is still land")
    assert.are_not.equal("out-of-map", tile(390, 0), "the ice ocean edge is still land")
  end)

  -- 2. TWO INTEGRATED, SOLID OCEANS ------------------------------------------------
  it("generates a SOLID hot-lava OCEAN at the sunward edge, zero gaps (ci-wly)", function()
    -- hot ocean band perp [200,400] -> x in [-400,-200]. Scan the interior.
    local box = { { -396, -RY }, { -204, RY } }
    local gaps = 0
    for _, name in ipairs(terrain.tile_names()) do
      if name ~= "cindra-lava-hot" then gaps = gaps + s.count_tiles_filtered({ name = name, area = box }) end
    end
    assert.are.equal(0, gaps, "the hot-lava ocean is a SOLID sea (found " .. gaps .. " non-lava-hot tiles)")
    assert.is_true(s.count_tiles_filtered({ name = "cindra-lava-hot", area = box }) > 1000, "large contiguous lava ocean")
  end)

  it("generates a SOLID smooth-ice OCEAN at the nightward edge -- INTEGRATED, not stamped (ci-wly/ci-7jc)", function()
    -- ice ocean band perp [-400,-200] -> x in [200,400]. The KEYSTONE cold-side fix: the
    -- ice ocean is the elevation PEAK of the cold heightmap, NOT a rectangle stamped over
    -- a finished map -- so it has no gaps and rings radiate inward from it.
    local box = { { 204, -RY }, { 396, RY } }
    local gaps = 0
    for _, name in ipairs(terrain.tile_names()) do
      if name ~= "cindra-ice-smooth" then gaps = gaps + s.count_tiles_filtered({ name = name, area = box }) end
    end
    assert.are.equal(0, gaps, "the smooth-ice ocean is a SOLID sea (found " .. gaps .. " non-ice-smooth tiles)")
    assert.is_true(s.count_tiles_filtered({ name = "cindra-ice-smooth", area = box }) > 1000, "large contiguous ice ocean")
  end)

  it("keeps BOTH oceans solid on OTHER seeds (seed-independent, ci-wly)", function()
    local base = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local fd = terrain.finite_dimension()
    for _, seed in ipairs({ 111, 99999 }) do
      local mgs = base.map_gen_settings
      mgs.seed = seed
      mgs[fd.key] = fd.value
      local sname = "cindra-ocean-seed-" .. seed
      local ss = game.surfaces[sname] or game.create_surface(sname, mgs)
      ss.request_to_generate_chunks({ 0, 0 }, 15)
      ss.force_generate_chunk_requests()
      local function gaps_in(core, x1, x2)
        local g = 0
        for _, name in ipairs(terrain.tile_names()) do
          if name ~= core then g = g + ss.count_tiles_filtered({ name = name, area = { { x1, -100 }, { x2, 100 } } }) end
        end
        return g
      end
      assert.are.equal(0, gaps_in("cindra-lava-hot", -396, -204), "seed " .. seed .. ": the lava ocean is still solid")
      assert.are.equal(0, gaps_in("cindra-ice-smooth", 204, 396), "seed " .. seed .. ": the ice ocean is still solid")
    end
  end)

  -- 3. HEIGHTMAP RINGS -------------------------------------------------------------
  it("rings every lava pool with hot crust: lava never directly touches non-hot terrain", function()
    local ring_smooth, ring_other, leaks, lava_seen = 0, 0, 0, 0
    for x = -396, -135, 1 do
      for y = -150, 150, 3 do
        if LAVA[tile(x, y)] then
          lava_seen = lava_seen + 1
          for _, d in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
            local n = tile(x + d[1], y + d[2])
            if not LAVA[n] then
              if n == "cindra-volcanic-smooth-stone-warm" then ring_smooth = ring_smooth + 1
              elseif HOT_CRUST[n] then ring_other = ring_other + 1
              else leaks = leaks + 1 end
            end
          end
        end
      end
    end
    assert.is_true(lava_seen > 50, "sampled a meaningful amount of lava (" .. lava_seen .. ")")
    assert.are.equal(0, leaks, "lava is always insulated by its hot-crust rings (leaks=" .. leaks .. ")")
    assert.is_true(ring_smooth >= ring_other, "the immediate ring around lava is predominantly smooth-stone-warm")
  end)

  it("rings the smooth-ice pools with cold crust: ice never directly touches middle/hot terrain", function()
    local ring, leaks, ice_seen = 0, 0, 0
    for x = 135, 396, 1 do
      for y = -150, 150, 3 do
        if tile(x, y) == "cindra-ice-smooth" then
          ice_seen = ice_seen + 1
          for _, d in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
            local n = tile(x + d[1], y + d[2])
            if n ~= "cindra-ice-smooth" then
              if COLD_RING[n] then ring = ring + 1 else leaks = leaks + 1 end
            end
          end
        end
      end
    end
    assert.is_true(ice_seen > 50, "sampled a meaningful amount of smooth ice (" .. ice_seen .. ")")
    assert.are.equal(0, leaks, "smooth-ice is always insulated by its cold rings (leaks=" .. leaks .. ")")
    assert.is_true(ring > 0, "smooth-ice pools are bounded by rough-ice / snow rings")
  end)

  it("gates both oceans by the gradient: dense at the map edge, thinning toward the middle", function()
    local lava_edge = count_in(LAVA, -396, -204, -RY, RY)
    local lava_mid = count_in(LAVA, -175, -135, -RY, RY)
    assert.is_true(lava_edge > lava_mid * 3, "lava thins toward the middle (edge=" .. lava_edge .. ", mid=" .. lava_mid .. ")")
    local ice_edge = s.count_tiles_filtered({ name = "cindra-ice-smooth", area = { { 204, -RY }, { 396, RY } } })
    local ice_mid = s.count_tiles_filtered({ name = "cindra-ice-smooth", area = { { 135, -RY }, { 175, RY } } })
    assert.is_true(ice_edge > ice_mid * 3, "smooth-ice thins toward the middle (edge=" .. ice_edge .. ", mid=" .. ice_mid .. ")")
  end)

  -- 4. THREE REGIONS ---------------------------------------------------------------
  -- Each region still READS as its own family, but it is no longer a pure one. The
  -- cosmetic scatter (ci-frcw) drops occasional patches of a neighbour's tile into it, on
  -- purpose -- ci-oe83 sanctioned exactly that soft bleed ("tiles MAY bleed/blend
  -- softly") to kill the three-stacked-bands look. So what is asserted is what a player
  -- actually reads: the region is DOMINATED by its own family, and every tile that bled
  -- in is COSMETIC ONLY -- harmless, walkable ground, never an ocean tile. The hard
  -- guards live below (no damaging ground in the safe corridor) and in test_heightmap
  -- (the belts stay unbypassable, the middle stays traversable).
  local function census(family, x1, x2)
    local own, bled, examples = 0, 0, {}
    for _, y in ipairs({ -120, -60, 0, 60, 120 }) do
      for x = x1, x2 do
        local n = tile(x, y)
        if family[n] then
          own = own + 1
        else
          bled = bled + 1
          examples[n] = (examples[n] or 0) + 1
          -- THE hard half: a bled tile must be pure decoration.
          local intensity = terrain.tile_damage(n)
          assert.are.equal(0, intensity,
            "a tile bled into a neighbouring region must be harmless; " .. n .. " at (" .. x .. "," .. y .. ")")
          assert.is_true(terrain.is_walkable(n) == true,
            "a tile bled into a neighbouring region must be walkable; " .. n .. " at (" .. x .. "," .. y .. ")")
        end
      end
    end
    return own / (own + bled), examples
  end

  it("keeps each region DOMINATED by its own tile family, bleeding only harmless ground", function()
    local hot = census(HOT_FAMILY, -195, -72)
    local middle = census(MIDDLE_FAMILY, -52, 52)
    local cold = census(COLD_FAMILY, 72, 195)
    log(string.format("ci-frcw own-family share: hot=%.3f middle=%.3f cold=%.3f", hot, middle, cold))
    -- Measured well above these; the floor is set to catch a scatter that has grown from
    -- flavour into a wash (which would read as one mushy planet, not three regions).
    assert.is_true(hot > 0.85, "the hot slope still reads hot (own-family share " .. hot .. ")")
    assert.is_true(middle > 0.85, "the middle still reads as the ash middle (own-family share " .. middle .. ")")
    assert.is_true(cold > 0.85, "the cold slope still reads cold (own-family share " .. cold .. ")")
  end)

  -- 4a. THE HOT-SIDE FOLDS BRANCH (ci-72bw) ----------------------------------------
  -- The safe hot slope carries TWO texture families over the same value segment, picked by
  -- a low-frequency branch noise: broad regions read folded/pumice, the rest read cracked.
  -- The slope spans perp (72, 130) -> x in (-130, -72).

  it("generates BOTH hot-slope families live: cracked regions AND folded/pumice regions (ci-72bw)", function()
    local folds = count_in(FOLDS, -128, -74, -RY, RY)
    local cracks = count_in(CRACKS, -128, -74, -RY, RY)
    assert.is_true(folds > 500, "the folds/pumice family really paints the hot slope (" .. folds .. " tiles)")
    assert.is_true(cracks > 500, "the cracks family still paints the hot slope (" .. cracks .. " tiles)")
    -- Every folds tile is present, not just the top of the family.
    for name in pairs(FOLDS) do
      assert.is_true(s.count_tiles_filtered({ name = name, area = { { -128, -RY }, { -74, RY } } }) > 0,
        name .. " generates somewhere on the hot slope")
    end
  end)

  it("picks ONE family per REGION (broad folded/cracked patches, not per-tile noise, ci-72bw)", function()
    -- Classify each sampled row by the family that dominates it. A low-frequency selector
    -- gives whole regions to one family; per-tile salt-and-pepper would give ~every row a
    -- 50/50 split and no clear winner.
    local folds_rows, cracks_rows = {}, {}
    for y = -150, 150, 5 do
      local f, c = 0, 0
      for x = -128, -74 do
        local n = tile(x, y)
        if FOLDS[n] then f = f + 1 elseif CRACKS[n] then c = c + 1 end
      end
      if f > c * 2 then folds_rows[#folds_rows + 1] = y
      elseif c > f * 2 then cracks_rows[#cracks_rows + 1] = y end
    end
    assert.is_true(#folds_rows > 0, "some regions of the hot slope read FOLDED (" .. #folds_rows .. " rows)")
    assert.is_true(#cracks_rows > 0, "some regions of the hot slope read CRACKED (" .. #cracks_rows .. " rows)")
  end)

  it("CONVERGES both families on ash-dark at the middle edge (ci-72bw)", function()
    -- Whichever family a region uses, its coldest member thins into ash-dark at the same
    -- value -- the two branches rejoin, so the middle never sees a family boundary.
    --
    -- A region is classified from the slope segment DIRECTLY OUTWARD of the measured band
    -- (perp 76..88, well under half a branch wavelength away) rather than from the whole
    -- slope: the branch noise turns over across the slope's own width, so a row that reads
    -- folded out near the crust can be a cracked region by the time it reaches the
    -- convergence, and grading the convergence by the far end measures that drift instead
    -- of the branch. It also samples the full generated length rather than 300 tiles of
    -- it, because the ci-frcw scatter paints in blobs and a short sample grades the blobs.
    --
    -- The band sits OUTWARD of the folds gate line (perp 64), so both families are equally
    -- free to paint it: the main line MAY bleed inward past that line (the ci-frcw
    -- scatter, the established look), the contained branch may not, and grading them where
    -- only one is allowed would compare the containment rule, not the convergence.
    local BAND_LO, BAND_HI = -74, -66
    local function local_family(y)
      local f, c = 0, 0
      for x = -88, -76 do
        local n = tile(x, y)
        if FOLDS[n] then f = f + 1 elseif CRACKS[n] then c = c + 1 end
      end
      if f > c then return "folds" elseif c > f then return "cracks" end
      return nil
    end
    local stat = {
      folds = { ash = 0, total = 0, hist = {} },
      cracks = { ash = 0, total = 0, hist = {} },
    }
    for y = -RY, RY, 3 do
      local fam = local_family(y)
      if fam then
        for x = BAND_LO, BAND_HI do
          local n = tile(x, y)
          local st = stat[fam]
          st.total = st.total + 1
          st.hist[n] = (st.hist[n] or 0) + 1
          if n == "cindra-volcanic-ash-dark" then st.ash = st.ash + 1 end
        end
      end
    end
    assert.is_true(stat.folds.total > 500 and stat.cracks.total > 500,
      "sampled a meaningful amount of both kinds of region (folds=" .. stat.folds.total ..
      ", cracks=" .. stat.cracks.total .. ")")
    local f_ash = stat.folds.ash / stat.folds.total
    local c_ash = stat.cracks.ash / stat.cracks.total
    log(string.format("ci-72bw convergence ash-dark share: folds=%.3f cracks=%.3f", f_ash, c_ash))
    -- Whichever family the region is, ash-dark is the ground the band is MADE of: the most
    -- common tile in it by a wide margin, and the majority of it.
    for fam, st in pairs(stat) do
      local top, top_n = nil, 0
      for n, c in pairs(st.hist) do
        if c > top_n then top, top_n = n, c end
      end
      assert.are.equal("cindra-volcanic-ash-dark", top,
        fam .. " regions must converge on ash-dark; the band's most common tile is " .. tostring(top))
    end
    -- The absolute floor is lower than ci-72bw shipped it, and deliberately so: the ci-frcw
    -- cosmetic scatter interleaves the slope's own ground into this band (and the ash back
    -- out into the slope) precisely so the transition stops reading as a line. Measured at
    -- ~0.52 / ~0.57; the floor catches a scatter that has grown until the convergence is
    -- no longer recognisably ash.
    assert.is_true(f_ash > 0.4, "folded regions converge on ash-dark (" .. f_ash .. ")")
    assert.is_true(c_ash > 0.4, "cracked regions converge on ash-dark (" .. c_ash .. ")")
    -- And they converge EQUALLY WELL: the branch does not push its own family further in
    -- (or stop it short) relative to the main line it branched from. This is the assertion
    -- ci-72bw exists for, and it keeps its original tightness.
    assert.is_true(math.abs(f_ash - c_ash) < 0.15,
      "both families reach ash-dark alike (folds=" .. f_ash .. ", cracks=" .. c_ash .. ")")
  end)

  it("never leaks folds tiles into the middle or the cold side (ci-72bw)", function()
    -- The branch lives strictly inside the hot slope's value segment, so no folds tile may
    -- appear from the middle band (x >= -60) rightward, all the way to the ice ocean.
    local leaked = count_in(FOLDS, -60, 396, -RY, RY)
    assert.are.equal(0, leaked, "folds-family tiles must never paint the middle/cold side (" .. leaked .. " found)")
    -- Nor above the branch: the lethal hot crust + the lava ocean stay the main line, so
    -- the branch adds no new zero-damage tile out in the heat belt.
    local hot_leak = count_in(FOLDS, -396, -135, -RY, RY)
    assert.are.equal(0, hot_leak, "folds-family tiles must never paint the lethal hot belt (" .. hot_leak .. " found)")
    -- Belt and braces: the whole scanned belt really is lethal ground.
    assert.are.equal("heat", terrain.lethal_at(135), "the scanned hot belt is heat-lethal")
  end)

  it("registers every folds tile as a real Cindra tile on the hot-slope gradient (ci-72bw)", function()
    -- That the folds ground is as HARMLESS as the cracks ground it alternates with is
    -- proven behaviourally, through the real damage sweep, in tests/test_tile_damage.lua;
    -- this pins the prototype side (registered, walkable, on the hot->cold colour ramp).
    for name in pairs(FOLDS) do
      assert.is_not_nil(prototypes.tile[name], name .. " is a real registered Cindra tile")
      assert.is_true(terrain.is_walkable(name), name .. " must be walkable ground")
      assert.is_not_nil(terrain.map_color(name), name .. " sits on the map-view gradient")
    end
  end)

  it("the habitable middle is a MIX of ash tiles (+ soil patches), not one flat tile", function()
    local seen = {}
    for x = -52, 52, 1 do
      for y = -120, 120, 8 do
        local n = tile(x, y)
        if MIDDLE_FAMILY[n] then seen[n] = true end
      end
    end
    local ash = 0
    for _, v in ipairs({ "cindra-volcanic-ash-dark", "cindra-volcanic-ash-light", "cindra-volcanic-ash-flats" }) do
      if seen[v] then ash = ash + 1 end
    end
    assert.is_true(ash >= 2, "the middle mixes at least two ash tiles, saw " .. ash)
    local soil = seen["cindra-volcanic-soil-dark"] or seen["cindra-volcanic-soil-light"] or seen["cindra-volcanic-ash-soil"]
    assert.is_true(soil == true, "the middle grows soil patches")
  end)

  -- 4b. THE COSMETIC CROSS-REGION SCATTER (ci-frcw) --------------------------------
  -- The bead's own words: an organic, less-banded look, bought by letting a point
  -- occasionally paint a tile a band or two from its own -- and bought SAFELY, because
  -- the scatter moves only the value the TILE is picked from, never the field the damage
  -- belts and the resource bands are read from.

  it("scatters NEIGHBOUR-REGION tiles across the middle: cool volcanic AND dust (ci-frcw)", function()
    -- Sampled in the middle's INTERIOR (|perp| <= 40), a long way inside the ordinary
    -- boundary wiggle + speckle bleed, so nothing here can be a band edge blurring: the
    -- only thing that can put a non-middle tile at these coordinates is the scatter.
    -- (Before ci-frcw this area was pure ash + soil, so the count below was zero.)
    local native = terrain.zone_tiles("middle")
    local seen, total, bled = {}, 0, 0
    for x = -40, 40 do
      for y = -200, 200, 4 do
        local n = tile(x, y)
        total = total + 1
        if not native[n] then bled = bled + 1; seen[n] = (seen[n] or 0) + 1 end
      end
    end
    local names = {}
    for n, c in pairs(seen) do names[#names + 1] = n .. "=" .. c end
    table.sort(names)
    log("ci-frcw middle scatter: " .. bled .. "/" .. total .. " -> " .. table.concat(names, " "))
    assert.is_true(bled > 0, "the middle really wears tiles that are not its own")
    -- Both directions: a patch of the hot side's cool volcanic ground AND a patch of the
    -- cold side's dust turn up out in the habitable band.
    assert.is_true((seen["cindra-volcanic-smooth-stone"] or 0) + (seen["cindra-volcanic-cracks"] or 0) > 0,
      "the middle wears patches of the cool volcanic slope")
    local dust = 0
    for _, v in ipairs({ "dust-flat", "dust-crests", "dust-lumpy", "dust-patchy" }) do
      dust = dust + (seen["cindra-" .. v] or 0)
    end
    assert.is_true(dust > 0, "the middle wears patches of the cold side's dust")
    -- Flavour, not a wash: the ash middle is still overwhelmingly ash.
    assert.is_true(bled / total < 0.25,
      "the scatter stays occasional (" .. string.format("%.3f", bled / total) .. " of the middle)")
    -- And every scattered tile is decoration: harmless, walkable, never an ocean tile.
    for n in pairs(seen) do
      assert.are.equal(0, (terrain.tile_damage(n)), n .. " scattered into the middle must be harmless")
      assert.is_true(terrain.is_walkable(n) == true, n .. " scattered into the middle must be walkable")
      assert.is_true(LAVA[n] ~= true and n ~= "cindra-ice-smooth",
        n .. " must never scatter into the middle (it is an ocean tile)")
    end
  end)

  it("leaks NO damaging ground anywhere the scatter can reach (ci-frcw)", function()
    -- THE hard guard the scatter has to earn: not one tile that burns or freezes exists
    -- in the corridor. Counted over the whole sampled band, every damaging tile named by
    -- the value ramp -- not sampled points, so a single leaked hot crack fails. (An
    -- unwindowed scatter really does leak them: it put glowing cracks-hot in the middle,
    -- which is what the ci-w87 glowing-rock and ci-i4z safe-band guards caught.)
    --
    -- The box is proven to COVER the scatter: the scatter is windowed shut outside the
    -- value range below, whose two contours are asserted to lie inside it. So this is not
    -- "no leak at the places we looked" -- it is "no leak anywhere a leak was possible".
    -- Further out, where the box ends, the ground is bit-identical to a world generated
    -- without this bead (the window is shut there), so the ci-4iw resource keep-back and
    -- its own guards still cover the rest.
    -- The window's two contours, in world tiles (perp = -x on this orientation), rounded
    -- OUTWARD so the box is a strict superset of the scatter-active band.
    local scatter_hot = terrain.field_crossing(terrain.HOT_DMG - terrain.SCATTER_GUARD_HOT)
    local scatter_cold = terrain.field_crossing(terrain.COLD_DMG + terrain.SCATTER_GUARD_COLD)
    assert.is_true(scatter_hot > 0 and scatter_cold < 0,
      "the scatter acts across the middle (perp " .. scatter_cold .. " .. " .. scatter_hot .. ")")
    local box = { { -math.ceil(scatter_hot), -RY }, { -math.floor(scatter_cold), RY } }
    log(string.format("ci-frcw scatter-active band: perp %.1f .. %.1f (x %d .. %d)",
      scatter_cold, scatter_hot, box[1][1], box[2][1]))
    for _, kind in ipairs({ "heat", "cold" }) do
      for _, name in ipairs(terrain.tiles_by_damage(kind)) do
        assert.are.equal(0, s.count_tiles_filtered({ name = name, area = box }),
          "no " .. kind .. "-damaging ground (" .. name .. ") may exist in the safe corridor")
      end
    end
    -- Not vacuous: those same tiles really do generate out in their own belts.
    local belts = 0
    for _, kind in ipairs({ "heat", "cold" }) do
      for _, name in ipairs(terrain.tiles_by_damage(kind)) do
        belts = belts + s.count_tiles_filtered({ name = name, area = { { -396, -RY }, { 396, RY } } })
      end
    end
    assert.is_true(belts > 1000, "damaging ground really does exist on this map (" .. belts .. " tiles)")
  end)

  it("draws ORGANIC (wavy) region boundaries, never raw straight lines", function()
    local first = {}
    for y = -160, 160, 10 do
      for x = 40, 120 do
        if COLD_FAMILY[tile(x, y)] and not MIDDLE_FAMILY[tile(x, y)] then first[#first + 1] = x; break end
      end
    end
    assert.is_true(#first >= 8, "sampled enough rows to judge the boundary")
    local lo, hi = first[1], first[1]
    for _, x in ipairs(first) do lo = math.min(lo, x); hi = math.max(hi, x) end
    assert.is_true(hi - lo >= 3, "the boundary wanders across rows (organic); spread=" .. tostring(hi - lo))
  end)

  -- 5. WALKABILITY -----------------------------------------------------------------
  it("makes ONLY the lava tiles impassable; smooth-ice is now walkable (ci-wly)", function()
    local function pave(name, cx, cy)
      local t = {}
      for x = cx - 4, cx + 4 do for y = cy - 4, cy + 4 do t[#t + 1] = { name = name, position = { x, y } } end end
      s.set_tiles(t, true)
    end
    local WY = 2600
    local function buildable(name)
      pave(name, 0, WY)
      return s.can_place_entity({ name = "stone-furnace", position = { 0, WY } })
    end
    assert.is_false(buildable("cindra-lava-hot"), "hot lava is impassable (unbuildable)")
    assert.is_false(buildable("cindra-lava"), "lava is impassable (unbuildable)")
    assert.is_true(buildable("cindra-ice-smooth"), "smooth-ice is now WALKABLE/buildable (you can run on it)")
    for _, walk in ipairs({ "cindra-volcanic-cracks-hot", "cindra-volcanic-ash-flats",
                            "cindra-dust-flat", "cindra-ice-rough", "cindra-snow-flat",
                            -- the ci-72bw folds branch is ordinary buildable slope ground
                            "cindra-volcanic-folds-warm", "cindra-volcanic-folds",
                            "cindra-volcanic-folds-flat", "cindra-volcanic-ash-cracks",
                            "cindra-volcanic-pumice-stones" }) do
      assert.is_true(buildable(walk), walk .. " is buildable ground")
    end
  end)

  -- 6. DAMAGE (positional descriptor) ----------------------------------------------
  it("flags the damage zones: hot ocean+inner (heat), cold inner+ocean (cold), middle safe", function()
    assert.are.equal("heat", terrain.lethal_at(-(-300)), "the hot-lava ocean is heat-lethal")
    assert.are.equal("heat", terrain.lethal_at(-(-150)), "the hot inner slope is heat-lethal")
    assert.are.equal("cold", terrain.lethal_at(-(150)), "the cold inner slope is cold-lethal")
    assert.are.equal("cold", terrain.lethal_at(-(300)), "the ice ocean is cold-lethal")
    assert.is_nil(terrain.lethal_at(-(0)), "the middle centre is safe")
    assert.is_nil(terrain.lethal_at(-(-90)), "the hot outer slope is safe")
    assert.is_nil(terrain.lethal_at(-(90)), "the cold outer slope is safe")
  end)

