  it("LANDABLE: the spawn tile + a base-sized pad are walkable, safe cindra ground", function()
    for x = -8, 8 do
      for y = -8, 8 do
        local n = tile(x, y)
        assert.matches("^cindra%-", n, "landing pad tile (" .. x .. "," .. y .. ") must be a cindra tile, got: " .. n)
        assert.is_true(terrain.is_walkable(n), "landing pad tile (" .. x .. "," .. y .. ") must be walkable, got: " .. n)
        -- Damage is positional now (ci-oe83): the spawn pad is in the safe middle band.
        assert.is_nil(terrain.lethal_at(-x), "landing pad column x=" .. x .. " must be damage-free (safe middle)")
      end
    end
  end)

  it("LANDABLE: a character dropped at spawn takes zero damage from a live tile-damage sweep", function()
    local char = s.create_entity({ name = "character", position = { 0, 0 }, force = "player" })
    assert.is_not_nil(char, "a character must be placeable at spawn")
    local before = char.health
    tile_damage.sweep(s, tile_damage.DAMAGE_INTERVAL, 200)
    assert.are.equal(before, char.health, "a character at the landing spot must take ZERO environmental damage")
    char.destroy()
  end)

  -- FINITE SURFACE + SLIDERS + MAP COLOUR -----------------------------------------
  it("bounds the REAL cindra planet surface at creation (the runtime hook works)", function()
    local live = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local mg = live.map_gen_settings
    assert.are.equal(800, mg.width, "the cindra surface is finite (800) on the perpendicular (X) axis")
    assert.is_true(mg.height == 0 or mg.height > 100000,
      "the ribbon is infinite along its long (Y) axis; got height=" .. tostring(mg.height))
  end)

  it("exposes real map-gen sliders: Stone + Ice are the only RESOURCE sliders", function()
    for _, n in ipairs({ "cindra-stone", "cindra-ice" }) do
      local ctrl = prototypes.autoplace_control[n]
      assert.is_not_nil(ctrl, n .. " autoplace-control exists")
      assert.are.equal("resource", ctrl.category, n .. " is a resource slider")
    end
    -- There is no standalone ice-derived ore (ci-3yl), so Cindra's map-gen screen must
    -- never grow a third RESOURCE slider. (It does carry terrain-category sliders for
    -- the ribbon geometry -- ci-i4z, tests/test_worldgen_sliders.lua.)
    local base = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local resource_sliders = {}
    for name in pairs(base.map_gen_settings.autoplace_controls) do
      local ctrl = prototypes.autoplace_control[name]
      if ctrl and ctrl.category == "resource" then resource_sliders[#resource_sliders + 1] = name end
    end
    table.sort(resource_sliders)
    assert.are.same({ "cindra-ice", "cindra-stone" }, resource_sliders,
      "exactly two resource sliders; got " .. table.concat(resource_sliders, ", "))
  end)

  it("marks the danger zones on the map: hot + cold edges carry a distinct map_color (ci-4h7)", function()
    local function mc(name)
      local c = prototypes.tile[name].map_color
      assert.is_not_nil(c, name .. " has a map_color")
      local scale = (c.r > 1 or c.g > 1 or c.b > 1) and 255 or 1
      return { c.r / scale, c.g / scale, c.b / scale }
    end
    local function dist(a, b) return math.abs(a[1]-b[1]) + math.abs(a[2]-b[2]) + math.abs(a[3]-b[3]) end
    local center = mc("cindra-volcanic-ash-flats")
    local lava, ice = mc("cindra-lava-hot"), mc("cindra-ice-smooth")
    assert.is_true(dist(lava, center) > 0.5, "the hot-lava danger edge is distinct from the middle")
    assert.is_true(dist(ice, center) > 0.4, "the deep-ice danger edge is distinct from the middle")
    assert.is_true(lava[1] > lava[2] and lava[1] > lava[3], "hot lava reads red/orange on the map")
    assert.is_true(ice[3] > ice[1], "deep ice reads cold (blue) on the map")
    local vlava = prototypes.tile["lava"]
    if vlava and vlava.map_color then
      local vs = (vlava.map_color.r > 1 or vlava.map_color.g > 1 or vlava.map_color.b > 1) and 255 or 1
      assert.is_true(dist(lava, { vlava.map_color.r / vs, vlava.map_color.g / vs, vlava.map_color.b / vs }) > 0.05,
        "Cindra hot-lava has its own map_color; vanilla lava is untouched")
    end
  end)
end)
